<template>
  <section class="billing-transactions" aria-labelledby="transaction-heading">
    <header><div><h2 id="transaction-heading">Billing transaction history</h2><p>Recorded payer payments, family payments, refunds, adjustments and patient responsibility.</p></div><button type="button" :disabled="loading" @click="load">Refresh transactions</button></header>
    <form class="transaction-filters" @submit.prevent="applySearch">
      <label class="search-field">Search transactions<input v-model="searchInput" placeholder="Patient, claim, payer or transaction" /></label>
      <label>Clinician<select v-model="pendingFilters.clinicianId" data-testid="transaction-clinician"><option value="">All clinicians</option><option v-for="choice in options.clinicians" :key="choice.value" :value="choice.value">{{ choice.label }}</option></select></label>
      <label>Service code<select v-model="pendingFilters.serviceCode" data-testid="transaction-service-code"><option value="">All service codes</option><option v-for="choice in options.serviceCodes" :key="choice.value" :value="choice.value">{{ choice.label }}</option></select></label>
      <label>Payer<select v-model="pendingFilters.payer" data-testid="transaction-payer"><option value="">All payers</option><option v-for="choice in options.payers" :key="choice.value" :value="choice.value">{{ choice.label }}</option></select></label>
      <label>Claim status<select v-model="pendingFilters.claimStatus" data-testid="transaction-claim-status"><option value="">All claim statuses</option><option v-for="choice in options.claimStatuses" :key="choice.value" :value="choice.value">{{ kindLabel(choice.label) }}</option></select></label>
      <label>Transaction type<select v-model="pendingFilters.transactionType" data-testid="transaction-type"><option value="">All transaction types</option><option v-for="choice in options.transactionTypes" :key="choice.value" :value="choice.value">{{ kindLabel(choice.label) }}</option></select></label>
      <fieldset><legend>Date of service</legend><label>From<input v-model="pendingFilters.serviceFrom" data-testid="transaction-service-from" type="date" :max="pendingFilters.serviceTo || undefined" /></label><label>Through<input v-model="pendingFilters.serviceTo" data-testid="transaction-service-to" type="date" :min="pendingFilters.serviceFrom || undefined" /></label></fieldset>
      <fieldset><legend>Posted date · America/Denver</legend><label>From<input v-model="pendingFilters.postedFrom" data-testid="transaction-posted-from" type="date" :max="pendingFilters.postedTo || undefined" /></label><label>Through<input v-model="pendingFilters.postedTo" data-testid="transaction-posted-to" type="date" :min="pendingFilters.postedFrom || undefined" /></label></fieldset>
      <div class="filter-actions"><label class="check"><input v-model="pendingFilters.includeDemo" type="checkbox" data-testid="transaction-include-demo" /> Include retained test records</label><button :disabled="loading">Apply filters</button><button type="button" :disabled="loading" @click="clearFilters">Clear filters</button></div>
    </form>
    <p v-if="hiddenTestRecords" class="test-record-note">{{ hiddenTestRecords }} test {{ hiddenTestRecords === 1 ? 'record is' : 'records are' }} excluded from this view and its totals. Their history is retained.</p>
    <p v-if="error" role="alert">{{ error }}</p><p v-if="loading" role="status">Loading transaction history…</p><p v-else-if="!available">Transaction history is unavailable until billing setup is complete.</p>
    <p v-if="!loading && available && !familyPaymentsAvailable" role="status">Payer transactions are available. Family payment history is not available for this scope.</p>
    <div v-if="!loading && available" class="table-scroll"><table><thead><tr><th v-for="column in columns" :key="column.id" :aria-sort="sortBy === column.id ? direction === 'asc' ? 'ascending' : 'descending' : 'none'"><button type="button" @click="sort(column.id)">{{ column.label }} {{ sortBy === column.id ? direction === 'asc' ? '↑' : '↓' : '↕' }}</button></th></tr></thead><tbody><tr v-for="item in rows" :key="`${item.agency_id}:${item.id}`"><td>{{ timestamp(item.posted_at) }}</td><td>{{ organization(item)?.name || 'Organization' }}</td><td><a :href="clientLink(item)">{{ item.client_name || `Client #${item.client_id}` }}</a><small v-if="item.is_demo_client || item.is_demo_source" class="test-badge">Test record</small><button v-if="item.claimId" class="link" type="button" @click="emit('open-claim', {...item, id:item.claimId, claimId:item.claimId, key:`claim:${item.claimId}`, source:'claim', readOnly:true})">{{ item.claim_reference || item.claim_number || `Claim #${item.claimId}` }}</button><small v-if="item.receipt_number">Receipt {{ item.receipt_number }}</small></td><td>{{ billingDate(item.date_of_service) }}</td><td>{{ item.provider_name || 'Not linked' }}</td><td>{{ (item.service_codes || [item.service_code]).filter(Boolean).join(', ') || 'Not linked' }}</td><td>{{ item.payer_name || 'Not recorded' }}</td><td>{{ kindLabel(item.claim_stage || item.claim_lifecycle || 'not_linked') }}</td><td>{{ kindLabel(item.kind) }}<small v-if="item.reverses_posting_id">Reverses transaction #{{ item.reverses_posting_id }}</small></td><td>{{ kindLabel(item.status) }}</td><td>{{ money(item.amount_cents) }}</td><td>{{ money(item.paid_cents) }}</td><td>{{ money(item.adjustment_cents) }}</td><td>{{ money(item.responsibility_cents) }}</td><td>{{ item.posted_by_name || 'Not recorded' }}</td></tr></tbody></table><p v-if="!rows.length" class="empty">No recorded transactions match this scope and filters.</p></div>
    <nav class="pagination" aria-label="Transaction pages"><span>{{ total }} transactions · Page {{ page }} of {{ Math.max(1, Math.ceil(total / pageSize)) }}</span><div><button :disabled="loading || page <= 1" @click="page--">Previous</button><button :disabled="loading || page * pageSize >= total" @click="page++">Next</button></div></nav>
  </section>
</template>
<script setup>
import { ref, reactive, watch, onBeforeUnmount } from 'vue';
import api from '../../services/api';
import { billingDate, claimStatusLabel } from '../../utils/billingWorkspace.js';
const props=defineProps({ agencyId:[String,Number], clientId:[String,Number] });
const emit=defineEmits(['open-claim']);
const emptyFilters=()=>({clinicianId:'',serviceCode:'',payer:'',claimStatus:'',transactionType:'',serviceFrom:'',serviceTo:'',postedFrom:'',postedTo:'',includeDemo:false});
const emptyOptions=()=>({clinicians:[],serviceCodes:[],payers:[],claimStatuses:[],transactionTypes:[]});
const pendingFilters=reactive(emptyFilters()),filters=ref(emptyFilters()),options=ref(emptyOptions());
const rows=ref([]),organizations=ref([]),loading=ref(false),error=ref(''),available=ref(true),familyPaymentsAvailable=ref(true),hiddenTestRecords=ref(0),total=ref(0),page=ref(1),pageSize=ref(30),searchInput=ref(''),search=ref(''),sortBy=ref('posted_at'),direction=ref('desc');
let sequence=0;
const columns=[['posted_at','Posted'],['organization','Organization'],['client_name','Patient / claim'],['date_of_service','Date of service'],['provider_name','Clinician'],['service_code','Service code'],['payer_name','Payer'],['claim_stage','Claim status'],['kind','Transaction'],['status','Transaction status'],['amount_cents','Transaction amount'],['paid_cents','Payment recorded'],['adjustment_cents','Adjustment'],['responsibility_cents','Patient responsibility'],['posted_by_name','Posted by']].map(([id,label])=>({id,label}));
const money=value=>value==null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(value)/100);
const timestamp=value=>{if(!value)return '—';const d=new Date(value);return Number.isNaN(d.getTime())?'—':d.toLocaleString('en-US',{timeZone:'America/Denver',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});};
const kindLabel=value=>({insurance_payment:'Insurance payment',adjudication:'Payer adjudication',reversal:'Reversal',adjustment:'Adjustment',succeeded:'Succeeded',pending:'Pending',failed:'Failed',refunded:'Refunded',posted:'Posted',not_linked:'No linked claim'}[value]||claimStatusLabel(value)||String(value||'Transaction').replaceAll('_',' '));
const organization=item=>organizations.value.find(org=>Number(org.id)===Number(item.agency_id));
const clientLink=item=>`${organization(item)?.slug?`/${encodeURIComponent(organization(item).slug)}`:''}/admin/clients/${Number(item.client_id)}?tab=billing&agencyId=${Number(item.agency_id)}`;
function applySearch(){search.value=searchInput.value.trim();filters.value={...pendingFilters};page.value=1;}
function clearFilters(){Object.assign(pendingFilters,emptyFilters());searchInput.value='';applySearch();}
function sort(id){direction.value=sortBy.value===id&&direction.value==='asc'?'desc':'asc';sortBy.value=id;page.value=1;}
async function load(){const current=++sequence;loading.value=true;error.value='';rows.value=[];try{const {data}=await api.get('/medical-billing/workspace/transactions',{params:{...(props.agencyId&&props.agencyId!=='all'?{agencyId:props.agencyId}:{}),...(props.clientId?{clientId:props.clientId}:{}),...Object.fromEntries(Object.entries(filters.value).filter(([,value])=>value!==''&&value!==false)),page:page.value,search:search.value,sortBy:sortBy.value,direction:direction.value},skipGlobalLoading:true});if(current!==sequence)return;rows.value=data.transactions||[];organizations.value=data.organizations||[];options.value={...emptyOptions(),...(data.filterOptions||{})};hiddenTestRecords.value=Number(data.hiddenTestRecords||0);total.value=Number(data.total||0);pageSize.value=Number(data.pageSize||30);available.value=data.available!==false;familyPaymentsAvailable.value=data.familyPaymentsAvailable!==false;}catch(e){if(current===sequence){error.value=e.response?.data?.error?.message||'Transaction history could not be loaded.';rows.value=[];total.value=0;}}finally{if(current===sequence)loading.value=false;}}
watch(()=>[props.agencyId,props.clientId],()=>{page.value=1;rows.value=[];options.value=emptyOptions();Object.assign(pendingFilters,emptyFilters());filters.value=emptyFilters();},{immediate:true});watch(()=>[props.agencyId,props.clientId,page.value,search.value,sortBy.value,direction.value,filters.value],load,{immediate:true});onBeforeUnmount(()=>sequence++);
</script>
<style scoped>
.billing-transactions{padding:22px;border:1px solid var(--app-line,#dfe6ef);border-radius:12px;background:var(--app-surface,#fff);margin-top:20px}header,.pagination{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}h2{margin:0;font-size:19px}p{color:var(--app-muted,#63718a);line-height:1.5}.transaction-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:20px 0;align-items:end}.transaction-filters label{display:grid;gap:6px;font-size:12px;min-width:0}.transaction-filters input,.transaction-filters select{width:100%;min-width:0;max-width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd8e5;border-radius:7px;background:var(--app-surface,#fff);font:inherit}.transaction-filters fieldset{display:flex;gap:12px;border:1px solid #dfe6ef;border-radius:8px;padding:10px;min-width:0}.transaction-filters fieldset label{flex:1}.transaction-filters legend{font-size:12px;color:#52647a}.filter-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;grid-column:1/-1}.filter-actions .check{display:flex;align-items:center;margin-right:auto}.check input{width:auto}.test-record-note{font-size:12px}.test-badge{color:#70571a}button{cursor:pointer;padding:9px 12px;border:1px solid #cbd8e5;border-radius:7px;background:var(--app-surface,#fff);color:var(--app-text-blue,#1555b0);font:inherit}button:disabled{opacity:.5;cursor:default}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px;text-align:left}th,td{padding:12px 10px;border-bottom:1px solid #e5ecf5;vertical-align:top;min-width:100px}th{background:#f4f7fb;font-size:11px;white-space:nowrap}th button,.link{padding:0;border:0;background:none;text-align:left}.link,small{display:block;margin-top:5px}a{color:#1555b0}.pagination{margin-top:18px;font-size:12px}.pagination>div{display:flex;gap:10px}[role=alert]{color:#a71925}@media(max-width:1000px){.transaction-filters{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.billing-transactions{padding:15px}.transaction-filters{grid-template-columns:1fr}.filter-actions .check{width:100%}.filter-actions button{flex:1}}
</style>
